"""One deterministic illustrative matched controlled exchange, not prevalence."""
from .common import *
from .dialogues import tex

def main():
 items=read(HERE/'inputs/compatibility_semantic.json');family=min({r['private']['identity']['family_id'] for r in items},key=lambda f:rank('auto008-controlled-illustration:'+f));chosen=sorted([r for r in items if r['private']['identity']['family_id']==family],key=lambda r:r['private']['identity']['condition']);assert len(chosen)==2
 report={'selection_rule':'Lowest SHA256(auto008-controlled-illustration:family_id) among prospectively selected32events; retrospective illustrative choice declared after objective outcomes, before reading these exchanges. No selection on words or judge labels.','family':family,'items':chosen};write(HERE/'inputs/CONTROLLED_DIALOGUE.json',report)
 out=['# Controlled dialogue illustration\n',report['selection_rule']+'\n'];paper=[r'\paragraph{Same field, different preference configuration.} A fifth illustrative panel uses the lowest hash-ranked family among the prospectively selected controlled semantic events. This retrospective presentation rule does not select for disagreement, novelty, or success. It is not an additional independent observation.']
 for r in chosen:
  i=r['private']['identity'];p=r['public'];out+=['## '+i['condition']+f" — {r['item_id']} · {family} · {i['world']} · opportunity {i['opportunity']}\n"]
  for key in ['recipient_previous','selected','first_followup','second_followup']:
   out+=[f"{key}:\n",'> '+p['blocks'][key]+'\n' if p['blocks'][key] else 'No recorded text.\n']
  out+=['Route and visibility (recorded): '+json.dumps({k:p[k] for k in ['route','delivered','selected_visible_to_recipient','selected_turn','first_followup_turn','second_followup_turn','delivered_text_truncated']})+'\n','Analyst-only authorized state: `'+json.dumps(r['private']['authorized'])+'`.\n',f"Answerer structured output at selected turn {p['selected_turn']} (before the later recipient opportunity): `"+json.dumps(r['private']['mechanical']['following_answer'])+'`.\n','Source: `'+json.dumps(r['private']['source_locator'])+'`.\n']
  paper +=[r'\textbf{'+tex(i['condition'].capitalize())+r':} selected statement at turn '+str(p['selected_turn'])+r': \begin{quote}\small '+tex(p['blocks']['selected'])+(r' \textit{[Delivered prefix truncated.]}' if p['delivered_text_truncated'] else '')+r'\end{quote}',r'Next recipient opportunity (turn '+str(p['first_followup_turn'])+r'): \begin{quote}\small '+(tex(p['blocks']['first_followup']) if p['blocks']['first_followup'] else r'\textit{No recorded text.}')+r'\end{quote}']
 paper +=[r"In both arms, the recipient had already made exactly the same statement before the selected message. The delivered message is visible at the next opportunity, but continued advocacy is not newly adopted wording. The user had authorized online participation at turn 16, and the answerer's turn-25 plan retains online in both arms, before the recipient's turn-28 opportunity. In the compatible arm, the recipient nevertheless advocates hybrid despite its configured onsite preference: the assignment is not a guarantee of behavioral compliance. The matched arms preserve the script, field, tools, and schedule, but their generated histories differ. This example illustrates what was delivered and followed; it does not identify a causal delivery effect or demonstrate strategic interaction."]
 (HERE/'CONTROLLED_DIALOGUE.md').write_text('\n'.join(out));(HERE/'paper/sections/controlled_dialogue.tex').write_text('\n\n'.join(paper)+'\n');print('Illustration selected:',family,[r['item_id'] for r in chosen])
if __name__=='__main__':main()
